function show(n){const pv=i;i=n;const a=N[n];$("hero").style.backgroundImage=`url('${art(n,...a.c,1)}')`;$("hk").textContent="PERSPEKTA "+a.k;$("hj").textContent=a.j;$("hd").textContent=a.d;$("ht").textContent=a.t;$("hw").textContent=a.w||"Tim Redaksi";
$("dots").innerHTML=`<span class="ab" role="button" aria-label="Sebelumnya" onclick="step(-1)">‹</span>`+N.map((_,k)=>`<button class="${k===n?"on":""}" aria-label="Berita ${k+1}" onclick="show(${k});auto()"></button>`).join("")+`<span class="ab" role="button" aria-label="Berikutnya" onclick="step(1)">›</span>`;const hc=document.querySelector(".hc");hc.classList.remove("sl","sr");void hc.offsetWidth;hc.classList.add(n>=pv?"sl":"sr")}
function auto(){clearInterval(T);T=setInterval(()=>show((i+1)%N.length),7000)}
$("lt").innerHTML=N.map((a,n)=>`<div class="li" onclick="show(${n});auto()"><img alt="" src="${art(n,...a.c)}"><div><b>${a.s}</b><span>${a.t}</span></div></div>`).join("");
